const data = $input.first().json.questionPaperData;

const errors = [];
if (!data) errors.push('No question-paper data received');
if (data && data.success !== true) errors.push('Upstream question-paper data was not marked successful');
if (data && !Array.isArray(data.sets)) errors.push('Question-paper data is missing "sets" array');
if (data && Array.isArray(data.sets) && data.sets.length === 0) errors.push('Question-paper data has zero sets');

return [{
  json: {
    data,
    validation: { valid: errors.length === 0, errors }
  }
}];

const data = $input.first().json.data;

return [{
  json: {
    exam: data.exam,
    sets: data.sets
  }
}];

// -----------------------------------------------------------------
// TEMPLATE NOTE
// -----------------------------------------------------------------
// No template image was attached to this build task, so this node
// implements the question-paper layout described in the spec (header,
// institution info, exam info, date area, instructions, Part-B question
// table with Q.No / Questions / Marks / RBL / Course Outcomes columns).
// If/when the real template image is available, only THIS node needs to
// change - it is fully isolated from question generation logic.
// -----------------------------------------------------------------
// This node runs in "Run Once for Each Item" mode: Split Sets emits one
// item per question-paper set (Set A, Set B, ...), and each must be
// turned into its own HTML document independently.

const item = $input.item.json;
const exam = item.exam;
const set = item.sets;

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const rows = set.questions.map(q => `
  <tr>
    <td class="qno">${esc(q.questionNumber)}</td>
    <td class="qtext">${esc(q.question)}</td>
    <td class="marks">${esc(q.marks)}</td>
    <td class="rbl">${esc(q.rbl)}</td>
    <td class="co">${Array.isArray(q.courseOutcomes) ? esc(q.courseOutcomes.join(', ')) : esc(q.courseOutcomes)}</td>
  </tr>`).join('\n');

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8" />
<style>
  @page { size: A4; margin: 18mm 14mm; }
  body { font-family: 'Times New Roman', serif; color: #111; font-size: 12pt; }
  .header { text-align: center; border-bottom: 2px solid #111; padding-bottom: 8px; margin-bottom: 10px; }
  .institution { font-size: 16pt; font-weight: bold; letter-spacing: 0.5px; }
  .exam-title { font-size: 13pt; margin-top: 4px; }
  .info-table { width: 100%; border-collapse: collapse; margin-bottom: 10px; font-size: 11pt; }
  .info-table td { padding: 3px 4px; }
  .instructions { font-size: 10.5pt; font-style: italic; margin-bottom: 10px; border-top: 1px solid #999; border-bottom: 1px solid #999; padding: 6px 0; }
  .part-title { font-weight: bold; text-align: center; margin: 14px 0 6px; text-decoration: underline; }
  table.questions { width: 100%; border-collapse: collapse; }
  table.questions th, table.questions td { border: 1px solid #111; padding: 6px 8px; vertical-align: top; }
  table.questions th { background: #f0f0f0; font-size: 10.5pt; }
  .qno { width: 6%; text-align: center; }
  .qtext { width: 58%; }
  .marks { width: 10%; text-align: center; }
  .rbl { width: 13%; text-align: center; }
  .co { width: 13%; text-align: center; }
  .set-badge { position: absolute; top: 10mm; right: 14mm; font-weight: bold; border: 1px solid #111; padding: 2px 8px; }
</style>
</head>
<body>
  <div class="set-badge">${esc(set.setName)}</div>
  <div class="header">
    <div class="institution">SCHOOL NAME / INSTITUTION</div>
    <div class="exam-title">${esc(exam.examType)} EXAMINATION - ${esc(exam.academicYear)}</div>
  </div>

  <table class="info-table">
    <tr>
      <td><b>Class:</b> ${esc(exam.class)}</td>
      <td><b>Section:</b> ${esc(exam.section)}</td>
      <td><b>Subject:</b> ${esc(exam.subject)}</td>
    </tr>
    <tr>
      <td><b>Time:</b> ${esc(exam.time)}</td>
      <td><b>Maximum Marks:</b> ${esc(exam.maximumMarks)}</td>
      <td><b>Date:</b> ___________________</td>
    </tr>
  </table>

  <div class="instructions">
    Instructions: Answer any <b>${esc(exam.questionsToAnswer)}</b> out of
    <b>${esc(exam.totalQuestions)}</b> questions. Each question carries
    <b>${esc(exam.marksPerQuestion)}</b> marks. Write answers legibly.
  </div>

  <div class="part-title">PART - B</div>

  <table class="questions">
    <thead>
      <tr>
        <th>Q.No</th>
        <th>Questions</th>
        <th>Marks</th>
        <th>RBL</th>
        <th>Course Outcomes</th>
      </tr>
    </thead>
    <tbody>
      ${rows}
    </tbody>
  </table>
</body>
</html>`;

return {
  json: {
    exam,
    setName: set.setName,
    fileName: `Question_Paper_${set.setName.replace(/\s+/g, '_')}.pdf`,
    html
  }
};

// Gotenberg's HTML route requires the HTML to arrive as an actual
// multipart file named 'index.html' (not JSON), so we convert the
// HTML string produced by 'Build HTML From Template' into a binary
// property here. No HTML content is changed.
const item = $input.item.json;
const htmlBuffer = Buffer.from(item.html, 'utf-8');

return {
  json: item,
  binary: {
    file: {
      data: htmlBuffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
};

// Guards against Workflow 03 reporting success when Gotenberg did not
// actually return a PDF (e.g. Gotenberg unreachable, wrong Docker
// hostname, or an error page instead of binary PDF data). Throwing
// here stops the workflow with a clear error instead of silently
// continuing to 'Save PDF' with bad/empty data.
const item = $input.item;
const fileName = (item.json && item.json.fileName) || 'question paper';
const binary = item.binary;

if (!binary || !binary.data) {
  throw new Error(
    `PDF generation failed for ${fileName}: Gotenberg did not return a PDF. ` +
    `Check that the Gotenberg container is running and reachable at ` +
    `${$env.GOTENBERG_URL || 'http://gotenberg:3000'} from the n8n container ` +
    `(same Docker network, correct service name).`
  );
}

if (binary.data.mimeType && binary.data.mimeType.indexOf('pdf') === -1) {
  throw new Error(
    `PDF generation failed for ${fileName}: Gotenberg returned content-type ` +
    `"${binary.data.mimeType}" instead of a PDF. This usually means Gotenberg ` +
    `returned an error page rather than a rendered document.`
  );
}

return item;

// This node runs in "Run Once for Each Item" mode, mirroring the one
// item per set that has flowed through the whole HTML -> PDF -> Save
// chain since "Split Sets". We read the set's name/fileName back from
// "Build HTML From Template" via the paired-item reference rather than
// depending on the exact output shape of the file-write node.
const htmlItem = $('Build HTML From Template').item.json;

return {
  json: {
    setName: htmlItem.setName,
    fileName: htmlItem.fileName,
    fileUrl: `/data/question-papers/${htmlItem.fileName}`
  }
};

const aggregated = $input.first().json;
// n8n's "Aggregate All Item Data" produces { data: [ {json...}, ... ] } by default
const documents = (aggregated.data || []).map(d => d.json ? d.json : d);

const exam = $('Validate Input').first().json.data.exam;

return [{
  json: {
    success: true,
    exam,
    documents
  }
}];

const j = $input.first().json;
return [{
  json: {
    success: false,
    error: {
      code: 'INVALID_DOCUMENT_INPUT',
      message: (j.validation && j.validation.errors.join('; ')) || 'Unknown document-generation error'
    }
  }
}];
